# 32x32 byte matrix multiply, blocked (MMC) with block size 8.
#   A at 0x2000, B at 0x3000, C at 0x4000.  Generated by
#   scripts/generate_matmul.py — DO NOT EDIT BY HAND.

_start:
    lui  sp, 0xC
    lui  s0, 0x2
    lui  s1, 0x3
    lui  s2, 0x4
    addi s3, x0, 32
    addi s11, x0, 8

    addi t0, x0, 0
    addi t1, x0, 1024
zero_c:
    bge  t0, t1, zero_done
    add  t2, s2, t0
    sb   x0, 0(t2)
    addi t0, t0, 1
    jal  x0, zero_c
zero_done:

    addi s4, x0, 0
ii_loop:
    bge  s4, s3, mm_end
    add  t3, s4, s11
    addi s5, x0, 0
jj_loop:
    bge  s5, s3, jj_end
    add  t4, s5, s11
    addi s7, x0, 0
kk_loop:
    bge  s7, s3, kk_end
    add  t5, s7, s11
    add  s8, s4, x0
i_loop:
    bge  s8, t3, i_end
    add  s9, s5, x0
j_loop:
    bge  s9, t4, j_end
    add  s10, s7, x0
    slli t0, s8, 5
    add  t0, t0, s9
    add  t0, s2, t0
    lb   gp, 0(t0)
k_loop:
    bge  s10, t5, k_end
    slli t1, s8, 5
    add  t1, t1, s10
    add  t1, s0, t1
    lb   a0, 0(t1)
    slli t2, s10, 5
    add  t2, t2, s9
    add  t2, s1, t2
    lb   a1, 0(t2)
    jal  ra, mul
    add  gp, gp, a0
    addi s10, s10, 1
    jal  x0, k_loop
k_end:
    sb   gp, 0(t0)
    addi s9, s9, 1
    jal  x0, j_loop
j_end:
    addi s8, s8, 1
    jal  x0, i_loop
i_end:
    add  s7, s7, s11
    jal  x0, kk_loop
kk_end:
    add  s5, s5, s11
    jal  x0, jj_loop
jj_end:
    add  s4, s4, s11
    jal  x0, ii_loop
mm_end:
    ebreak

mul:
    addi t6, x0, 0
    andi a1, a1, 0xff
    beq  a1, x0, mul_done
mul_loop:
    add  t6, t6, a0
    addi a1, a1, -1
    bne  a1, x0, mul_loop
mul_done:
    add  a0, t6, x0
    jalr x0, 0(ra)
